-- Tables first created with attributes only, no keys:
CREATE TABLE Member (MemberID CHARACTER(4), MemberName VARCHAR(30), Junior BOOLEAN, DateJoined DATE);
CREATE TABLE Booking (BookingNo INTEGER, MemberID CHARACTER(4), ClassName VARCHAR(20),
                      ClassDate DATE, StartTime TIME, Fee REAL);

-- Keys added afterwards:
ALTER TABLE Member ADD PRIMARY KEY (MemberID);
ALTER TABLE Booking ADD PRIMARY KEY (BookingNo);
ALTER TABLE Booking ADD FOREIGN KEY (MemberID) REFERENCES Member(MemberID);

-- A later change of design: store a phone number for each member
ALTER TABLE Member ADD Phone VARCHAR(15);
-- Every existing member now has a Phone attribute with no value yet.

INSERT INTO Member (MemberID, MemberName, Junior, DateJoined)
VALUES ('M104', 'O. Haddad', FALSE, '2024-03-15');

INSERT INTO Booking
VALUES (1, 'M104', 'Yoga', '2026-10-05', '18:00', 6.00);

-- Rejected: there is no member M999, so the foreign key check fails
INSERT INTO Booking
VALUES (9, 'M999', 'Spin', '2026-10-13', '07:30', 8.00);

UPDATE Booking
SET Fee = 7.50
WHERE ClassName = 'Pilates';
-- Changes 2 records: bookings 4 and 5 now have Fee 7.50. The other six are unchanged.

-- T. Reyes (M120) leaves the centre:
DELETE FROM Member WHERE MemberID = 'M120';
-- Rejected: bookings 4 and 7 still refer to M120.

DELETE FROM Booking WHERE MemberID = 'M120';
-- Removes bookings 4 and 7.
DELETE FROM Member WHERE MemberID = 'M120';
-- Now succeeds: Member has 3 records.

-- Check: SELECT COUNT(*), SUM(Fee) FROM Booking;
-- Bookings left: 1 (6.00), 2 (8.00), 3 (6.00), 5 (7.50), 6 (8.00), 8 (6.00)
COUNT(*) | SUM(Fee)
6        | 41.50
